// src/features/Education/hooks/useProgress.js
import { useState, useEffect } from 'react';

const useProgress = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Inicializar el progreso con valores por defecto
  useEffect(() => {
    try {
      // Verificar si ya hay datos de progreso
      const hasProgress = localStorage.getItem('overall_progress');
      
      // Si no hay datos, inicializar con valores por defecto
      if (!hasProgress) {
        localStorage.setItem('overall_progress', '0');
      }
      
      setLoading(false);
    } catch (error) {
      console.error('Error initializing progress data:', error);
      setError('No se pudo inicializar los datos de progreso');
      setLoading(false);
    }
  }, []);
  
  // Obtener progreso de un curso específico
  const getProgress = (courseId) => {
    if (!courseId) return 0;
    
    try {
      const progress = localStorage.getItem(`course_progress_${courseId}`);
      return progress ? parseInt(progress, 10) : 0;
    } catch (error) {
      console.error(`Error getting progress for course ${courseId}:`, error);
      return 0;
    }
  };
  
  // Obtener progreso general
  const getOverallProgress = () => {
    try {
      const progress = localStorage.getItem('overall_progress');
      return progress ? parseInt(progress, 10) : 0;
    } catch (error) {
      console.error('Error getting overall progress:', error);
      return 0;
    }
  };
  
  // Actualizar progreso de un curso
  const updateProgress = (courseId, type, itemId) => {
    if (!courseId) return;
    
    try {
      // Obtener lecciones completadas
      const completedLessons = JSON.parse(
        localStorage.getItem(`course_${courseId}_completed_lessons`) || '[]'
      );
      
      // Si es una lección y no está en la lista, añadirla
      if (type === 'lessons' && !completedLessons.includes(itemId)) {
        completedLessons.push(itemId);
        localStorage.setItem(
          `course_${courseId}_completed_lessons`, 
          JSON.stringify(completedLessons)
        );
      }
      
      // Calcular progreso basado en lecciones completadas
      // Aquí deberíamos tener el total de lecciones, pero para simplificar
      // asumimos que cada lección completada es un 20% de progreso
      const progress = Math.min(completedLessons.length * 20, 100);
      
      // Guardar progreso
      localStorage.setItem(`course_progress_${courseId}`, progress.toString());
      
      return progress;
    } catch (error) {
      console.error(`Error updating progress for course ${courseId}:`, error);
      return getProgress(courseId);
    }
  };
  
  // Marcar lección como completada
  const markLessonComplete = (courseId, lessonId) => {
    if (!courseId || !lessonId) return false;
    
    try {
      return updateProgress(courseId, 'lessons', lessonId);
    } catch (error) {
      console.error(`Error marking lesson ${lessonId} as complete:`, error);
      return false;
    }
  };
  
  // Verificar si una lección está completada
  const isLessonCompleted = (courseId, lessonId) => {
    if (!courseId || !lessonId) return false;
    
    try {
      const completedLessons = JSON.parse(
        localStorage.getItem(`course_${courseId}_completed_lessons`) || '[]'
      );
      return completedLessons.includes(lessonId);
    } catch (error) {
      console.error(`Error checking if lesson ${lessonId} is completed:`, error);
      return false;
    }
  };
  
  // Obtener árbol seleccionado
  const getSelectedTree = (courseId) => {
    if (!courseId) return null;
    
    try {
      const treeData = localStorage.getItem(`course_${courseId}_selected_tree`);
      return treeData ? JSON.parse(treeData) : null;
    } catch (error) {
      console.error(`Error getting selected tree for course ${courseId}:`, error);
      return null;
    }
  };
  
  // Guardar árbol seleccionado
  const saveSelectedTree = (courseId, treeData) => {
    if (!courseId || !treeData) return false;
    
    try {
      localStorage.setItem(`course_${courseId}_selected_tree`, JSON.stringify(treeData));
      return true;
    } catch (error) {
      console.error(`Error saving selected tree for course ${courseId}:`, error);
      return false;
    }
  };
  
  return {
    loading,
    error,
    getProgress,
    getOverallProgress,
    updateProgress,
    markLessonComplete,
    isLessonCompleted,
    getSelectedTree,
    saveSelectedTree
  };
};

export default useProgress;